const FLOW_PLAIN = new Map<string, PlainLabel>();
for (const entry of FLOW_PLAIN_ENTRIES) {
  const [zh, newZh, newEn] = entry.length === 4 ? [entry[0], entry[2], entry[3]] : entry;
  FLOW_PLAIN.set(zh, [newZh, newEn]);
}

/**
 * Returns the beginner-facing label for a control-flow node or edge. Labels
 * not present in the table are already prose and pass through unchanged.
 */
export function plainFlowLabel(zh: string, en: string, lang: 'zh' | 'en'): string {
  const plain = FLOW_PLAIN.get(zh);
  if (plain) return lang === 'zh' ? plain[0] : plain[1];
  return lang === 'zh' ? zh : en;
}

