const FLOW_SUMMARIES = new Map<string, PlainLabel>();
for (const [zh, , newZh, newEn] of FLOW_SUMMARY_ENTRIES) {
  FLOW_SUMMARIES.set(zh, [newZh, newEn]);
}

/** Returns the beginner-facing section intro shown above a control-flow graph. */
export function plainFlowSummary(zh: string, en: string, lang: 'zh' | 'en'): string {
  const plain = FLOW_SUMMARIES.get(zh);
  if (plain) return lang === 'zh' ? plain[0] : plain[1];
  return lang === 'zh' ? zh : en;
}

